    routerOptions: {
      maxParamLength: 2048
    }
  }

  const app1 = Fastify(options)
  const app2 = Fastify(options)

  t.after(() => Promise.all([
    app1.close(),
    app2.close()
  ]))

  const response = await app2.inject('/not-found')
  t.assert.strictEqual(response.statusCode, 404)
})

